193	export function getTrainingPlanAllocationAdjustmentHistory(
194	  fundingDetails: Record<string, unknown> | null | undefined,
195	  allocationId?: string,
196	) {
197	  const details = fundingDetails as
198	    | TrainingPlanFundingDetails
199	    | null
200	    | undefined;
201	  const history = Array.isArray(details?.allocationAdjustmentHistory)
202	    ? details.allocationAdjustmentHistory.filter(
203	        isAllocationAdjustmentHistoryEntry,
204	      )
205	    : [];
206	  const filtered = allocationId
207	    ? history.filter((entry) => entry.allocationId === allocationId)
208	    : history;
209	  return filtered
210	    .slice()
211	    .sort(
212	      (a, b) =>
213	        new Date(b.adjustedAt).getTime() - new Date(a.adjustedAt).getTime(),
214	    );
215	}
