217	export function applyHoursToActiveTrainingPlanCourse(
218	  fundingDetails: Record<string, unknown> | null | undefined,
219	  hours: TrainingPlanEventHours,
220	) {
221	  const details: TrainingPlanFundingDetails = { ...(fundingDetails ?? {}) };
222	  const courseAllocations = getTrainingPlanCourseAllocations(details).map(
223	    (allocation) => ({ ...allocation }),
224	  );
225	  if (courseAllocations.length === 0) {
226	    return {
227	      applied: false,
228	      activeCourseName: null,
229	      fundingDetails: details,
230	    };
231	  }
232	
233	  const requestedIndex = Number(details.currentCourseIndex);
234	  const activeIndex = Number.isInteger(requestedIndex)
235	    ? Math.min(Math.max(requestedIndex, 0), courseAllocations.length - 1)
236	    : Math.max(
237	        0,
238	        courseAllocations.findIndex(
239	          (allocation) => allocation.status === 'active',
240	        ),
241	      );
242	  const active = courseAllocations[activeIndex];
243	  active.flightHoursUsed =
244	    safeHours(active.flightHoursUsed) + safeHours(hours.flight);
245	  active.groundHoursUsed =
246	    safeHours(active.groundHoursUsed) + safeHours(hours.ground);
247	  active.simulatorHoursUsed =
248	    safeHours(active.simulatorHoursUsed) + safeHours(hours.simulator);
249	
250	  const flightComplete =
251	    safeHours(active.flightHoursTotal) === 0 ||
252	    active.flightHoursUsed >= safeHours(active.flightHoursTotal);
253	  const groundComplete =
254	    safeHours(active.groundHoursTotal) === 0 ||
255	    active.groundHoursUsed >= safeHours(active.groundHoursTotal);
256	  const simulatorComplete =
257	    safeHours(active.simulatorHoursTotal) === 0 ||
258	    active.simulatorHoursUsed >= safeHours(active.simulatorHoursTotal);
259	  active.status =
260	    flightComplete && groundComplete && simulatorComplete
261	      ? 'hours_complete'
262	      : 'active';
263	
264	  details.currentCourseIndex = activeIndex;
265	  details.courseAllocations = courseAllocations;
266	  return {
267	    applied: true,
268	    activeCourseName: active.name,
269	    fundingDetails: details,
270	  };
271	}
